19	#define MIEM_NC_CHECK(call)                                                    \
20	  do {                                                                         \
21	    const int nc_status_ = (call);                                             \
22	    if (nc_status_ != NC_NOERR) {                                              \
23	      throw ::miem::MiemException(MIEM_ERROR_CATEGORY_IO,                      \
24	                                  MIEM_IO_ERROR_CODE_NETCDF,                   \
25	                                  std::string("NetCDF error: ") +             \
26	                                  nc_strerror(nc_status_));                    \
27	    }                                                                          \
