30	namespace miem {
31	
32	namespace {
33	
34	// Accept any of these calendars (or missing). Anything else is a hard
35	// UnsupportedCalendar error.
36	bool IsAcceptedCalendar(const std::string& cal)
37	{
38	  return cal.empty() ||
39	         cal == "gregorian" ||
40	         cal == "proleptic_gregorian" ||
41	         cal == "standard";
42	}
43	
44	bool ParseCFTimeUnits(const std::string& units_str,
45	                      double&            multiplier,
46	                      double&            ref_epoch)
47	{
48	  // CF time units are "<unit> since <ISO-8601 datetime>",
49	  // e.g. "seconds since 2012-01-01 00:00:00".
50	  const std::string::size_type since = units_str.find(" since ");
51	  if (since == std::string::npos)
52	  {
53	    return false;
54	  }
55	
56	  const std::string unit = units_str.substr(0, since);
57	  if (unit == "seconds" || unit == "second" || unit == "s")
58	  {
59	    multiplier = 1.0;
60	  }
61	  else if (unit == "minutes" || unit == "minute")
62	  {
63	    multiplier = 60.0;
64	  }
65	  else if (unit == "hours" || unit == "hour" || unit == "h")
66	  {
67	    multiplier = 3600.0;
68	  }
69	  else if (unit == "days" || unit == "day" || unit == "d")
70	  {
71	    multiplier = 86400.0;
72	  }
73	  else
74	  {
75	    return false;
76	  }
77	
78	  // Parse the reference datetime: a "YYYY-MM-DD" date, an optional
79	  // "[ T]HH:MM[:SS]" time, an optional fractional second, and an optional
80	  // UTC offset -- e.g. "2012-01-01", "...00:00:00", "...00:00:00.5",
81	  // "...00:00:00 +01:00", or both. UDUNITS/CF permit the fraction and the
82	  // offset, so we honour them instead of silently dropping them; anything
83	  // left unconsumed at the end is treated as malformed. (std::chrono::parse
84	  // would be tidier but isn't available across all of our toolchains yet.)
85	  const std::string when   = units_str.substr(since + 7);
86	  const char*       cursor = when.data();
87	  const char* const end    = when.data() + when.size();
88	
89	  // Read an integer, then require/consume `delim` (unless delim == '\0').
90	  const auto take = [&](int& out, char delim) -> bool {
91	    const auto [next, ec] = std::from_chars(cursor, end, out);
92	    if (ec != std::errc{})
93	    {
94	      return false;
95	    }
96	    cursor = next;
97	    if (delim != '\0')
98	    {
99	      if (cursor == end || *cursor != delim)
100	      {
101	        return false;
102	      }
103	      ++cursor;
104	    }
105	    return true;
106	  };
107	
108	  int year = 0, month = 0, day = 0, hour = 0, minute = 0, second = 0;
109	  if (!take(year, '-') || !take(month, '-') || !take(day, '\0'))
110	  {
111	    return false;
112	  }
113	
114	  double frac_seconds   = 0.0;
115	  double offset_seconds = 0.0;
116	
117	  if (cursor != end && (*cursor == ' ' || *cursor == 'T'))
118	  {
119	    ++cursor;
120	    if (!take(hour, ':') || !take(minute, '\0'))
121	    {
122	      return false;
123	    }
124	    if (cursor != end && *cursor == ':')
125	    {
126	      ++cursor;
127	      if (!take(second, '\0'))
128	      {
129	        return false;
130	      }
131	    }
132	
133	    // Optional fractional second (".5", ".250", ...). Accumulated as a
134	    // double so it survives into ref_epoch.
135	    if (cursor != end && *cursor == '.')
136	    {
137	      ++cursor;
138	      double scale = 0.1;
139	      bool   any   = false;
140	      for (; cursor != end && *cursor >= '0' && *cursor <= '9'; ++cursor)
141	      {
142	        frac_seconds += (*cursor - '0') * scale;
143	        scale *= 0.1;
144	        any = true;
145	      }
146	      if (!any)  // a lone '.' with no digits
147	      {
148	        return false;
149	      }
150	    }
151	
152	    // Optional UTC offset: "Z", or a signed offset in any of the three
153	    // accepted forms -- "+HH:MM", "+HHMM" (compact), or "+HH" (and the
154	    // negative forms). A reference given at an offset is that many hours
155	    // ahead of UTC, so we subtract it below.
156	    if (cursor != end && *cursor == ' ')
157	    {
158	      ++cursor;
159	    }
160	    if (cursor != end && (*cursor == 'Z' || *cursor == 'z'))
161	    {
162	      ++cursor;  // explicit UTC; offset stays zero
163	    }
164	    else if (cursor != end && (*cursor == '+' || *cursor == '-'))
165	    {
166	      const int sign = (*cursor == '-') ? -1 : 1;
167	      ++cursor;
168	
169	      // Parse the digit groups explicitly: from_chars is greedy, so "0130"
170	      // would read as 130 rather than 01h30m. Count the leading run instead.
171	      const char* const digits_begin = cursor;
172	      while (cursor != end && *cursor >= '0' && *cursor <= '9')
173	      {
174	        ++cursor;
175	      }
176	      const auto n_digits = cursor - digits_begin;
177	
178	      int off_hour = 0, off_min = 0;
179	      if (cursor != end && *cursor == ':')
180	      {
181	        // "HH:MM": 1-2 hour digits, then exactly two minute digits.
182	        if (n_digits < 1 || n_digits > 2)
183	        {
184	          return false;
185	        }
186	        std::from_chars(digits_begin, cursor, off_hour);
187	        ++cursor;  // consume ':'
188	        const char* const min_begin = cursor;
189	        while (cursor != end && *cursor >= '0' && *cursor <= '9')
190	        {
191	          ++cursor;
192	        }
193	        if (cursor - min_begin != 2)
194	        {
195	          return false;
196	        }
197	        std::from_chars(min_begin, cursor, off_min);
198	      }
199	      else if (n_digits == 4)
200	      {
201	        std::from_chars(digits_begin, digits_begin + 2, off_hour);  // "HHMM"
202	        std::from_chars(digits_begin + 2, cursor, off_min);
203	      }
204	      else if (n_digits == 1 || n_digits == 2)
205	      {
206	        std::from_chars(digits_begin, cursor, off_hour);  // "HH"
207	      }
208	      else
209	      {
210	        return false;  // e.g. 3 digits, or no digits -- unrecognized
211	      }
212	      offset_seconds = sign * (off_hour * 3600.0 + off_min * 60.0);
213	    }
214	  }
215	
216	  // Reject anything we could not account for rather than silently ignoring
217	  // a malformed or unsupported units string.
218	  for (; cursor != end && *cursor == ' '; ++cursor)
219	  {
220	  }
221	  if (cursor != end)
222	  {
223	    return false;
224	  }
225	
226	  // UTC reference instant = the calendar fields, less the offset, plus any
227	  // fractional second. ref_epoch is a double, so sub-second precision is
228	  // preserved.
229	  const std::chrono::sys_seconds tp =
230	      UtcTimePoint(year, month, day, hour, minute, second);
231	  ref_epoch = static_cast<double>(tp.time_since_epoch().count()) +
232	              frac_seconds - offset_seconds;
233	  return true;
234	}
