240	  if (status != NC_NOERR || att_len == 0 || att_len > 4096)
241	  {
242	    return {};
243	  }
244	  std::string value(att_len, '\0');
245	  if (nc_get_att_text(ncid, varid, name.c_str(), value.data()) != NC_NOERR)
246	  {
247	    return {};
248	  }
249	  return value;
