270	  return nc_get_var_float(ncid, varid, out);
271	}
272	int NcGetAttFill(int ncid, int varid, const char* name, double* out)
273	{
274	  return nc_get_att_double(ncid, varid, name, out);
275	}
276	int NcGetAttFill(int ncid, int varid, const char* name, float* out)
