283	ECCADReader::ECCADReader(ECCADReader&& other) noexcept
284	    : ncid_(other.ncid_),
285	      file_path_(std::move(other.file_path_)),
286	      eccad_version_(std::move(other.eccad_version_)),
287	      n_time_steps_(other.n_time_steps_),
288	      n_cells_(other.n_cells_),
289	      available_species_(std::move(other.available_species_))
290	{
291	  other.ncid_ = -1;
292	}
293	
294	ECCADReader& ECCADReader::operator=(ECCADReader&& other) noexcept
295	{
296	  if (this != &other)
297	  {
298	    Close();
299	    ncid_              = other.ncid_;
300	    file_path_         = std::move(other.file_path_);
301	    eccad_version_     = std::move(other.eccad_version_);
302	    n_time_steps_      = other.n_time_steps_;
303	    n_cells_           = other.n_cells_;
304	    available_species_ = std::move(other.available_species_);
305	    other.ncid_        = -1;
306	  }
307	  return *this;
308	}
309	
310	void ECCADReader::Open(const std::string& file_path)
311	{
312	  if (ncid_ >= 0)
313	  {
314	    Close();
315	  }
316	
317	  file_path_ = file_path;
318	
319	  const int status = nc_open(file_path.c_str(), NC_NOWRITE, &ncid_);
320	  if (status != NC_NOERR)
321	  {
322	    throw MiemException(MIEM_ERROR_CATEGORY_IO,
323	                        MIEM_IO_ERROR_CODE_FILE_NOT_FOUND,
324	                        "Failed to open NetCDF file: " + file_path +
325	                        " — " + nc_strerror(status));
326	  }
327	
328	  DetectFormat();
329	  DiscoverSpecies();
330	}
331	
332	void ECCADReader::Close()
333	{
334	  if (ncid_ >= 0)
335	  {
336	    nc_close(ncid_);
337	    ncid_ = -1;
338	  }
339	  available_species_.clear();
340	  n_time_steps_ = 0;
341	  n_cells_      = 0;
342	}
343	
344	void ECCADReader::DetectFormat()
345	{
346	  // ECCAD compliance is signalled by the `eccad_version` (preferred) or
347	  // legacy `ses_version` global attribute. If neither is present the file
348	  // is not ECCAD/SES-conformant, so refuse rather than guess.
349	  eccad_version_ = ReadTextAttribute(ncid_, NC_GLOBAL, "eccad_version");
350	  if (eccad_version_.empty())
351	  {
352	    eccad_version_ = ReadTextAttribute(ncid_, NC_GLOBAL, "ses_version");
353	  }
354	  if (eccad_version_.empty())
355	  {
356	    throw MiemException(
357	        MIEM_ERROR_CATEGORY_IO, MIEM_IO_ERROR_CODE_INVALID_FORMAT,
358	        "ECCADReader: file '" + file_path_ +
359	        "' has neither 'eccad_version' nor 'ses_version' global "
360	        "attribute; refer to docs/eccad.md.");
361	  }
362	
363	  // Time dimension (optional — a single-snapshot file may omit it).
364	  int        time_dim_id;
365	  const int  ts = nc_inq_dimid(ncid_, "time", &time_dim_id);
366	  if (ts == NC_NOERR)
367	  {
368	    std::size_t len;
369	    MIEM_NC_CHECK(nc_inq_dimlen(ncid_, time_dim_id, &len));
370	    n_time_steps_ = static_cast<int>(len);
371	  }
372	  else
373	  {
374	    n_time_steps_ = 1;
375	  }
376	
377	  // Cell dimension is required.
378	  int       cell_dim_id;
379	  const int cs = nc_inq_dimid(ncid_, "n_cells", &cell_dim_id);
380	  if (cs != NC_NOERR)
381	  {
382	    throw MiemException(MIEM_ERROR_CATEGORY_IO,
383	                        MIEM_IO_ERROR_CODE_INVALID_FORMAT,
384	                        "ECCADReader: dimension 'n_cells' missing in: " +
385	                        file_path_);
386	  }
387	  std::size_t cell_len;
388	  MIEM_NC_CHECK(nc_inq_dimlen(ncid_, cell_dim_id, &cell_len));
389	  n_cells_ = static_cast<int>(cell_len);
390	}
391	
392	void ECCADReader::DiscoverSpecies()
393	{
394	  available_species_.clear();
395	
396	  int n_vars;
397	  MIEM_NC_CHECK(nc_inq_nvars(ncid_, &n_vars));
398	
399	  // ECCAD names each emission variable "emi_<species>" (e.g. emi_co);
400	  // strip the prefix to recover the species name.
401	  static const std::string kPrefix = "emi_";
402	  std::set<std::string> seen;
403	  for (int varid = 0; varid < n_vars; ++varid)
404	  {
405	    char raw_name[NC_MAX_NAME + 1];
406	    MIEM_NC_CHECK(nc_inq_varname(ncid_, varid, raw_name));
407	
408	    const std::string name(raw_name);
409	    if (name.size() > kPrefix.size() &&
410	        name.compare(0, kPrefix.size(), kPrefix) == 0)
411	    {
412	      std::string species = name.substr(kPrefix.size());
413	      if (seen.insert(species).second)
414	      {
415	        available_species_.push_back(std::move(species));
416	      }
417	    }
418	  }
419	}
420	
421	std::vector<std::string> ECCADReader::QuerySpecies() const
422	{
423	  return available_species_;
424	}
425	
426	std::vector<double> ECCADReader::GetTimeValues() const
427	{
428	  std::vector<double> times(n_time_steps_, 0.0);
429	
430	  int       time_varid;
431	  const int status = nc_inq_varid(ncid_, "time", &time_varid);
432	  if (status != NC_NOERR)
433	  {
434	    // A single-snapshot file (no `time` dimension, n_time_steps_ == 1)
435	    // may legitimately omit the `time` variable -- treat as t = 0.
436	    // Anything else is a malformed file: refuse to silently fabricate
437	    // zero-valued times.
438	    if (n_time_steps_ > 1)
439	    {
440	      throw MiemException(
441	          MIEM_ERROR_CATEGORY_IO, MIEM_IO_ERROR_CODE_INVALID_FORMAT,
442	          "ECCADReader: file '" + file_path_ + "' has a 'time' "
443	          "dimension of length " + std::to_string(n_time_steps_) +
444	          " but no 'time' variable; refusing to fabricate zero-valued "
445	          "time coordinates.");
446	    }
447	    return times;  // legitimate single-snapshot file
448	  }
449	
450	  MIEM_NC_CHECK(nc_get_var_double(ncid_, time_varid, times.data()));
451	
452	  const std::string units_str    = ReadTextAttribute(ncid_, time_varid, "units");
453	  const std::string calendar_str = ReadTextAttribute(ncid_, time_varid, "calendar");
454	
455	  if (units_str.empty())
456	  {
457	    throw MiemException(
458	        MIEM_ERROR_CATEGORY_IO, MIEM_IO_ERROR_CODE_INVALID_TIME_UNITS,
459	        "ECCADReader: time variable in " + file_path_ +
460	        " is missing the required 'units' attribute.");
461	  }
462	
463	  if (!IsAcceptedCalendar(calendar_str))
464	  {
465	    throw MiemException(
466	        MIEM_ERROR_CATEGORY_IO, MIEM_IO_ERROR_CODE_UNSUPPORTED_CALENDAR,
467	        "ECCADReader: unsupported time calendar '" + calendar_str +
468	        "' in " + file_path_ +
469	        ". v1 supports only gregorian / proleptic_gregorian / standard / "
470	        "missing.");
471	  }
472	
473	  double multiplier = 1.0;
474	  double ref_epoch  = 0.0;
475	  if (!ParseCFTimeUnits(units_str, multiplier, ref_epoch))
476	  {
477	    throw MiemException(
478	        MIEM_ERROR_CATEGORY_IO, MIEM_IO_ERROR_CODE_INVALID_TIME_UNITS,
479	        "ECCADReader: invalid CF time units '" + units_str +
480	        "' in " + file_path_);
481	  }
482	
483	  for (auto& t : times)
484	  {
485	    t = t * multiplier + ref_epoch;
486	  }
487	
488	  return times;
489	}
490	
491	void ECCADReader::ReadFlux(int                             time_index,
492	                           const std::vector<std::string>& species_names,
493	                           std::vector<Real>&              flux_out,
494	                           int&                            n_cells_out) const
495	{
496	  if (ncid_ < 0)
497	  {
498	    throw MiemException(MIEM_ERROR_CATEGORY_IO,
499	                        MIEM_IO_ERROR_CODE_FILE_NOT_FOUND,
500	                        "ECCADReader: file not open");
501	  }
502	
503	  n_cells_out               = n_cells_;
504	  const int n_species       = static_cast<int>(species_names.size());
505	  flux_out.assign(static_cast<std::size_t>(n_species) * n_cells_, Real{ 0 });
506	
507	  for (int isp = 0; isp < n_species; ++isp)
508	  {
509	    const std::string var_name = "emi_" + species_names[isp];
510	
511	    int       varid;
512	    const int look = nc_inq_varid(ncid_, var_name.c_str(), &varid);
513	    if (look != NC_NOERR)
514	    {
515	      continue;  // species absent in this file — leave zeros
516	    }
517	
518	    int ndims;
519	    MIEM_NC_CHECK(nc_inq_varndims(ncid_, varid, &ndims));
520	
521	    std::vector<Real> raw(n_cells_, Real{ 0 });
522	
523	    if (ndims == 2)
524	    {
525	      const std::size_t start[2] = { static_cast<std::size_t>(time_index), 0 };
526	      const std::size_t count[2] = { 1, static_cast<std::size_t>(n_cells_) };
527	      MIEM_NC_CHECK(NcGetVara(ncid_, varid, start, count, raw.data()));
528	    }
529	    else if (ndims == 1)
530	    {
531	      MIEM_NC_CHECK(NcGetVar(ncid_, varid, raw.data()));
532	    }
533	    else
534	    {
535	      continue;
536	    }
537	
538	    Real fill_value = Real{ 0 };
539	    bool has_fill   = false;
540	    Real fv{};
541	    if (NcGetAttFill(ncid_, varid, "_FillValue", &fv) == NC_NOERR)
542	    {
543	      fill_value = fv;
544	      has_fill   = true;
545	    }
546	
547	    for (int ic = 0; ic < n_cells_; ++ic)
548	    {
549	      Real val = raw[ic];
550	      if (has_fill && val == fill_value)
551	      {
552	        val = Real{ 0 };
553	      }
554	      flux_out[static_cast<std::size_t>(isp) * n_cells_ + ic] = val;
555	    }
556	  }
557	}
558	
559	}  // namespace miem
