3	//
4	// End-to-end integration test — the issue #6 vehicle.
5	//
6	// Acceptance criterion from issue #6: "an integration test which gets
7	// emissions for NO2, NO, and O3 is created".  This test:
8	//
9	//   1. Generates a synthetic ECCAD NetCDF holding emi_NOx = 1.0e-9
10	//      kg/m^2/s and emi_O3 = 5.0e-10 kg/m^2/s on N cells, at multiple
11	//      time steps.
12	//   2. Assembles an Emissions module (via EmissionsBuilder) with one
13	//      source: NOx -> NO @ 0.9 + NOx -> NO2 @ 0.1, O3 -> O3 @ 1.0
14	//      (identity), anthropogenic sector.
15	//   3. Calls Emissions::Run at one or more times.
16	//   4. Asserts:
17	//        - surface_flux(NO)  == 0.9 * 1e-9 = 9.0e-10 +/- 1e-22
18	//        - surface_flux(NO2) == 0.1 * 1e-9 = 1.0e-10 +/- 1e-22
19	//        - surface_flux(O3)  == 5.0e-10 (identity passthrough)
20	//   5. With air_density + layer_thickness provided: tendency matches
21	//      surface_flux / (rho * dz) within tolerance.
22	
23	#include "synthetic_nc.hpp"
24	
25	#include <miem/source_types.hpp>
26	#include <miem/emissions_state.hpp>
27	#include <miem/emissions.hpp>
28	#include <miem/emissions_builder.hpp>
29	#include <miem/util/types.hpp>
30	
31	#include <gtest/gtest.h>
32	
33	#include <memory>
34	#include <string>
35	#include <type_traits>
36	#include <vector>
37	
38	using namespace miem;
39	using miem_test::CreateTestNetCDF;
40	using miem_test::TempDir;
41	
42	namespace {
43	
44	constexpr int    kNCells     = 8;
45	constexpr int    kNVertLevels = 5;
46	constexpr double kNOxFlux    = 1.0e-9;   // kg/m^2/s
47	constexpr double kO3Flux     = 5.0e-10;  // kg/m^2/s
48	
49	// Precision-aware tolerance: at 1e-9 magnitude the double round-off is
50	// ~1e-25; for float32 it's ~1e-16.  Use ~1e-15 for float so sum-of-
51	// products noise is absorbed without losing algorithmic-drift catch.
52	constexpr double kFluxTol =
53	    std::is_same_v<miem::Real, double> ? 1.0e-22 : 1.0e-15;
54	constexpr double kTendTol =
55	    std::is_same_v<miem::Real, double> ? 1.0e-25 : 1.0e-18;
56	
57	// Build the test NetCDF.  Two time steps so the linear blend at the
58	// midpoint gives the same flux back (constant-in-time inventory).
59	std::string MakeIntegrationFile(const TempDir& dir)
60	{
61	  const std::string path = dir.File("integration_inventory.nc");
62	  std::vector<double> nox(2 * kNCells, kNOxFlux);
63	  std::vector<double> o3 (2 * kNCells, kO3Flux);
64	  CreateTestNetCDF(path, /*n_times=*/2, /*n_cells=*/kNCells,
65	                   /*time_values=*/{ 0.0, 3600.0 },
66	                   /*species=*/{ "NOx", "O3" },
67	                   /*flux_data=*/{ nox, o3 });
68	  return path;
69	}
70	
71	}  // namespace
72	
73	// ---------------------------------------------------------------------
74	// Surface-flux-only run.
75	// ---------------------------------------------------------------------
76	TEST(NoxPipelineIntegrationTest, NOxSplitAndO3Passthrough)
77	{
78	  TempDir dir;
79	  const std::string path = MakeIntegrationFile(dir);
80	
81	  Source src;
82	  src.name_                   = "test_inventory";
83	  src.file_pattern_           = path;
84	  src.convention_             = "eccad";
85	  src.temporal_interpolation_ = TemporalInterpolation::Linear;
86	  src.vertical_injection_     = VerticalInjection::Surface;
87	  // HEMCO aggregation indices (open-ended ints): with a single source these
88	  // don't matter; across sources, categories sum and the higher hierarchy
89	  // wins per cell.
90	  src.category_               = 0;
91	  src.hierarchy_              = 1;
92	  src.sector_                 = "anthropogenic";
93	
94	  // NOx -> NO 0.9 + NO2 0.1.  Plus O3 identity passthrough.
95	  src.species_map_.AddMapping("NOx", "NO",  0.9);
96	  src.species_map_.AddMapping("NOx", "NO2", 0.1);
97	  src.species_map_.AddMapping("O3",  "O3",  1.0);
98	
99	  Emissions module = EmissionsBuilder()
100	                         .SetGridDimensions(kNCells, kNVertLevels)
101	                         .AddSource(src)
102	                         .Build();
103	
104	  // Run at midpoint t=1800s (between 0 and 3600); inventory is constant
105	  // so the blend equals the input flux.
106	  const auto state = module.Run(/*time_sec=*/1800.0, /*dt=*/60.0);
107	
108	  // Assertion: per-cell surface flux for NO / NO2 / O3.
109	  for (int ic = 0; ic < kNCells; ++ic)
110	  {
111	    EXPECT_NEAR(static_cast<double>(state.surface_flux_(ic, "NO")),
112	                0.9 * kNOxFlux, kFluxTol);     // 9.0e-10
113	    EXPECT_NEAR(static_cast<double>(state.surface_flux_(ic, "NO2")),
114	                0.1 * kNOxFlux, kFluxTol);     // 1.0e-10
115	    EXPECT_NEAR(static_cast<double>(state.surface_flux_(ic, "O3")),
116	                kO3Flux,        kFluxTol);     // 5.0e-10
117	  }
118	
119	  // Sector flux for "anthropogenic" should reflect all three species.
120	  const EmissionsArray* sec = state.GetSectorFlux("anthropogenic");
121	  ASSERT_NE(sec, nullptr);
122	  for (int ic = 0; ic < kNCells; ++ic)
123	  {
124	    EXPECT_NEAR(static_cast<double>((*sec)(ic, "NO")),
125	                0.9 * kNOxFlux, kFluxTol);
126	    EXPECT_NEAR(static_cast<double>((*sec)(ic, "NO2")),
127	                0.1 * kNOxFlux, kFluxTol);
128	    EXPECT_NEAR(static_cast<double>((*sec)(ic, "O3")),
129	                kO3Flux,        kFluxTol);
130	  }
131	}
132	
133	// ---------------------------------------------------------------------
134	// Same pipeline, with air_density + layer_thickness -> tendency_
135	// matches surface_flux / (rho * dz) at the surface injection layer.
136	// ---------------------------------------------------------------------
137	TEST(NoxPipelineIntegrationTest, TendencyMatchesFluxOverColumnIntegrand)
138	{
139	  TempDir dir;
140	  const std::string path = MakeIntegrationFile(dir);
141	
142	  Source src;
143	  src.name_                   = "test_inventory";
144	  src.file_pattern_           = path;
145	  src.convention_             = "eccad";
146	  src.species_map_.AddMapping("NOx", "NO",  0.9);
147	  src.species_map_.AddMapping("NOx", "NO2", 0.1);
148	  src.species_map_.AddMapping("O3",  "O3",  1.0);
149	
150	  Emissions module = EmissionsBuilder()
151	                         .SetGridDimensions(kNCells, kNVertLevels)
152	                         .AddSource(src)
153	                         .Build();
154	
155	  const Real kRho = static_cast<Real>(1.225);
156	  const Real kDz  = static_cast<Real>(100.0);
157	  std::vector<Real> rho(kNVertLevels * kNCells, kRho);
158	  std::vector<Real> dz (kNVertLevels * kNCells, kDz);
159	
160	  const auto state = module.Run(/*time_sec=*/1800.0, /*dt=*/60.0,
161	                                 rho.data(), dz.data(),
162	                                 kNVertLevels * kNCells);
163	
164	  // For each species, tendency at level 0 should be surface_flux/(rho*dz).
165	  // Find species indices by name in state.species_names_.
166	  auto find_idx = [&](const std::string& s) -> int {
167	    for (int i = 0; i < static_cast<int>(state.species_names_.size()); ++i)
168	    {
169	      if (state.species_names_[i] == s) return i;
170	    }
171	    return -1;
172	  };
173	  const int i_no  = find_idx("NO");
174	  const int i_no2 = find_idx("NO2");
175	  const int i_o3  = find_idx("O3");
176	  ASSERT_GE(i_no,  0);
177	  ASSERT_GE(i_no2, 0);
178	  ASSERT_GE(i_o3,  0);
179	
180	  auto tend_at = [&](int isp, int lv, int ic) -> Real {
181	    return state.tendency_[
182	        static_cast<std::size_t>(isp) * kNVertLevels * kNCells +
183	        static_cast<std::size_t>(lv) * kNCells + ic];
184	  };
185	
186	  // Layer 0 (surface): non-zero; other layers: zero.
187	  for (int ic = 0; ic < kNCells; ++ic)
188	  {
189	    EXPECT_NEAR(static_cast<double>(tend_at(i_no,  0, ic)),
190	                (0.9 * kNOxFlux) / (1.225 * 100.0), kTendTol);
191	    EXPECT_NEAR(static_cast<double>(tend_at(i_no2, 0, ic)),
192	                (0.1 * kNOxFlux) / (1.225 * 100.0), kTendTol);
193	    EXPECT_NEAR(static_cast<double>(tend_at(i_o3,  0, ic)),
194	                kO3Flux         / (1.225 * 100.0), kTendTol);
195	
196	    for (int lv = 1; lv < kNVertLevels; ++lv)
197	    {
198	      EXPECT_EQ(tend_at(i_no,  lv, ic), Real{ 0 });
199	      EXPECT_EQ(tend_at(i_no2, lv, ic), Real{ 0 });
200	      EXPECT_EQ(tend_at(i_o3,  lv, ic), Real{ 0 });
201	    }
202	  }
203	
204	  // Column-integrated tendency * rho * dz round-trips to surface_flux
205	  // within the post-S1 tolerance (1e-9 relative + 1e-18 absolute floor).
206	  for (int isp = 0; isp < static_cast<int>(state.species_names_.size());
207	       ++isp)
208	  {
209	    for (int ic = 0; ic < kNCells; ++ic)
210	    {
211	      Real sum = Real{ 0 };
212	      for (int lv = 0; lv < kNVertLevels; ++lv)
213	      {
214	        sum += tend_at(isp, lv, ic) *
215	               rho[lv * kNCells + ic] *
216	               dz [lv * kNCells + ic];
217	      }
218	      const Real flux = state.surface_flux_.At(isp, ic);
219	      EXPECT_NEAR(static_cast<double>(sum), static_cast<double>(flux),
220	                  1.0e-6 * static_cast<double>(flux) + kFluxTol);
221	    }
222	  }
223	}
224	
225	// ---------------------------------------------------------------------
226	// Repeating the run at a different time within the bracket yields the
227	// same flux (constant inventory) — sanity check on the temporal loop.
228	// ---------------------------------------------------------------------
229	TEST(NoxPipelineIntegrationTest, RepeatedRunsRespectTimeBracket)
230	{
231	  TempDir dir;
232	  const std::string path = MakeIntegrationFile(dir);
233	
234	  Source src;
235	  src.name_                   = "test_inventory";
236	  src.file_pattern_           = path;
237	  src.convention_             = "eccad";
238	  src.species_map_.AddMapping("NOx", "NO",  0.9);
239	  src.species_map_.AddMapping("NOx", "NO2", 0.1);
240	  src.species_map_.AddMapping("O3",  "O3",  1.0);
241	
242	  Emissions module = EmissionsBuilder()
243	                         .SetGridDimensions(kNCells, kNVertLevels)
244	                         .AddSource(src)
245	                         .Build();
246	
247	  for (double t : { 100.0, 1800.0, 3500.0 })
248	  {
249	    const auto state = module.Run(t, 60.0);
250	    EXPECT_NEAR(static_cast<double>(state.surface_flux_(0, "NO")),
251	                0.9 * kNOxFlux, kFluxTol);
252	    EXPECT_NEAR(static_cast<double>(state.surface_flux_(0, "NO2")),
253	                0.1 * kNOxFlux, kFluxTol);
254	    EXPECT_NEAR(static_cast<double>(state.surface_flux_(0, "O3")),
255	                kO3Flux,        kFluxTol);
256	  }
257	}
