27	
28	// The invariant checks, run once at Build() time.  Throws on the first
29	// violation (MICM-aligned: no multi-error accumulation).  Invariants:
30	//   - regridding must be RegriddingType::None
31	//   - each source's convention must be "eccad" (case-insensitive)
32	//   - each source's mode must be SourceMode::Offline
33	//   - each source's vertical injection must be VerticalInjection::Surface
34	//   - each source's species map must validate (scaling sum <= 1.0)
35	//   - (category, hierarchy) must be unique across sources
36	void EmissionsBuilder::Validate() const
37	{
38	  // Regridding type must be None.
39	  if (regridding_.type_ != RegriddingType::None)
40	  {
41	    throw MiemException(
42	        MIEM_ERROR_CATEGORY_CONFIGURATION,
43	        MIEM_CONFIGURATION_ERROR_CODE_UNSUPPORTED_REGRIDDING,
44	        "EmissionsBuilder: only Regridding::None is supported in v1.");
45	  }
46	
47	  // Track (category, hierarchy) to flag duplicates.
48	  std::set<std::pair<int, int>> cat_hier;
49	
50	  for (const auto& src : sources_)
51	  {
52	    // Convention must be ECCAD.
53	    if (ToLower(src.convention_) != "eccad")
54	    {
55	      throw MiemException(
56	          MIEM_ERROR_CATEGORY_CONFIGURATION,
57	          MIEM_CONFIGURATION_ERROR_CODE_UNKNOWN_CONVENTION,
58	          "Source '" + src.name_ + "': unknown convention '" +
59	          src.convention_ + "' — v1 supports only 'eccad'.");
60	    }
61	
62	    // Mode must be Offline.
63	    if (src.mode_ != SourceMode::Offline)
64	    {
65	      throw MiemException(
66	          MIEM_ERROR_CATEGORY_CONFIGURATION,
67	          MIEM_CONFIGURATION_ERROR_CODE_ONLINE_NOT_SUPPORTED,
68	          "Source '" + src.name_ + "': online sources are not "
69	          "supported in v1.");
70	    }
71	
72	    // Vertical injection must be Surface.
73	    if (src.vertical_injection_ != VerticalInjection::Surface)
74	    {
75	      throw MiemException(
76	          MIEM_ERROR_CATEGORY_CONFIGURATION,
77	          MIEM_CONFIGURATION_ERROR_CODE_UNSUPPORTED_VERTICAL_INJECTION,
78	          "Source '" + src.name_ + "': only "
79	          "VerticalInjection::Surface is supported in v1.");
80	    }
81	
82	    // Species map invariants (scaling sum <= 1.0).  Rethrow with the
83	    // offending source name for context while preserving category/code.
84	    try
85	    {
86	      src.species_map_.Validate();
87	    }
88	    catch (const MiemException& e)
