}

void UptempoReader::Open(const std::string& file_path)
{
  if (ncid_ >= 0)
  {
    Close();
  }

  file_path_ = file_path;

  const int status = nc_open(file_path.c_str(), NC_NOWRITE, &ncid_);
  if (status != NC_NOERR)
  {
    throw MiemException(MIEM_ERROR_CATEGORY_IO,
                        MIEM_IO_ERROR_CODE_FILE_NOT_FOUND,
                        "Failed to open NetCDF file: " + file_path +
                        " — " + nc_strerror(status));
  }

  DetectDimensions();
  DiscoverSpecies();
}

void UptempoReader::Close()
{
  if (ncid_ >= 0)
  {
    nc_close(ncid_);
    ncid_ = -1;
  }
  available_species_.clear();
  n_time_steps_ = 0;
  n_cells_      = 0;
  time_dim_id_  = -1;
  cell_dim_id_  = -1;
}

void UptempoReader::DetectDimensions()
{
