79	      const SyntheticNcOptions& opts)
80	  {
81	    int ncid = -1;
82	    NcCheck(nc_create(path.c_str(), NC_CLOBBER | NC_NETCDF4, &ncid), "nc_create");
83	
84	    // Global attributes.  Either the modern eccad_version or the legacy
85	    // ses_version (or neither, by setting both empty in opts) — the reader
86	    // accepts both.
87	    if (!opts.eccad_version.empty())
88	    {
89	      nc_put_att_text(ncid, NC_GLOBAL, "eccad_version", opts.eccad_version.size(), opts.eccad_version.c_str());
90	    }
91	    if (!opts.ses_version.empty())
92	    {
93	      nc_put_att_text(ncid, NC_GLOBAL, "ses_version", opts.ses_version.size(), opts.ses_version.c_str());
