99	    int time_dim = -1;
100	    int cell_dim = -1;
101	    NcCheck(nc_def_dim(ncid, "time", static_cast<std::size_t>(n_times), &time_dim), "nc_def_dim(time)");
102	    NcCheck(nc_def_dim(ncid, "n_cells", static_cast<std::size_t>(n_cells), &cell_dim), "nc_def_dim(n_cells)");
103	
104	    // Time variable (omitted when opts.omit_time_variable is set)
105	    int time_varid = -1;
106	    if (!opts.omit_time_variable)
107	    {
108	      NcCheck(nc_def_var(ncid, "time", NC_DOUBLE, 1, &time_dim, &time_varid), "nc_def_var(time)");
109	      if (!opts.time_units.empty())
110	      {
111	        nc_put_att_text(ncid, time_varid, "units", opts.time_units.size(), opts.time_units.c_str());
112	      }
113	      if (!opts.calendar.empty())
114	      {
115	        nc_put_att_text(ncid, time_varid, "calendar", opts.calendar.size(), opts.calendar.c_str());
116	      }
