118	
119	    // Species flux variables: (time, n_cells)
120	    std::vector<int> flux_varids(species.size(), -1);
121	    int dims2d[2] = { time_dim, cell_dim };
122	    for (std::size_t i = 0; i < species.size(); ++i)
123	    {
124	      const std::string var_name = "emi_" + species[i];
125	      NcCheck(nc_def_var(ncid, var_name.c_str(), NC_DOUBLE, 2, dims2d, &flux_varids[i]), "nc_def_var(" + var_name + ")");
126	    }
127	
128	    NcCheck(nc_enddef(ncid), "nc_enddef");
129	
130	    // Write time values (only if the variable exists).
131	    if (time_varid >= 0)
