145	void CreateUptempoTestNetCDF(const std::string&                      path,
146	                             int                                     n_times,
147	                             int                                     n_cells,
148	                             const std::vector<std::string>&         xtime_stamps,
149	                             const std::vector<std::string>&         variables,
150	                             const std::vector<std::vector<double>>& flux_data,
151	                             const UptempoNcOptions&                 opts)
152	{
153	  constexpr int kStrLen = 64;
154	
155	  int ncid = -1;
156	  NcCheck(nc_create(path.c_str(), NC_CLOBBER | NC_NETCDF4, &ncid), "nc_create");
157	
158	  // Dimensions: Time, nCells, StrLen.  Deliberately no version attribute --
159	  // the UPTEMPO layout is identified by its dimensions, not a marker.
160	  int time_dim = -1;
161	  int cell_dim = -1;
162	  int str_dim  = -1;
163	  NcCheck(nc_def_dim(ncid, "Time",
164	                     static_cast<std::size_t>(n_times), &time_dim),
165	          "nc_def_dim(Time)");
166	  NcCheck(nc_def_dim(ncid, "nCells",
167	                     static_cast<std::size_t>(n_cells), &cell_dim),
168	          "nc_def_dim(nCells)");
169	  NcCheck(nc_def_dim(ncid, "StrLen", kStrLen, &str_dim), "nc_def_dim(StrLen)");
170	
171	  // MPAS xtime: char(Time, StrLen).
172	  int xtime_varid = -1;
173	  if (!opts.omit_xtime)
174	  {
175	    int xtime_dims[2] = { time_dim, str_dim };
176	    NcCheck(nc_def_var(ncid, "xtime", NC_CHAR, 2, xtime_dims, &xtime_varid),
177	            "nc_def_var(xtime)");
178	    if (!opts.calendar.empty())
179	    {
180	      nc_put_att_text(ncid, xtime_varid, "calendar",
181	                      opts.calendar.size(), opts.calendar.c_str());
182	    }
183	  }
184	
185	  // Flux variables: (Time, nCells), named exactly as requested.
186	  std::vector<int> flux_varids(variables.size(), -1);
187	  int dims2d[2] = { time_dim, cell_dim };
188	  const double nan_value = std::nan("");
