190	  {
191	    NcCheck(nc_def_var(ncid, variables[i].c_str(), NC_DOUBLE, 2, dims2d,
192	                       &flux_varids[i]),
193	            "nc_def_var(" + variables[i] + ")");
194	    if (opts.nan_fill)
195	    {
196	      nc_put_att_double(ncid, flux_varids[i], "_FillValue", NC_DOUBLE, 1,
