211	      const std::size_t   len =
212	          std::min<std::size_t>(stamp.size(), kStrLen);
213	      std::memcpy(buffer.data() + static_cast<std::size_t>(t) * kStrLen,
214	                  stamp.data(), len);
215	    }
216	    NcCheck(nc_put_var_text(ncid, xtime_varid, buffer.data()),
217	            "nc_put_var_text(xtime)");
