27	    // Strip the fixed-width padding NetCDF char variables carry: cut at the
28	    // first NUL, then drop trailing spaces.
29	    std::string TrimFixedWidth(const std::string& raw)
30	    {
31	      std::string s = raw.substr(0, raw.find('\0'));
32	      while (!s.empty() && s.back() == ' ')
33	      {
34	        s.pop_back();
35	      }
36	      return s;
37	    }
38	
39	    // Parse an MPAS `xtime` stamp -- "YYYY-MM-DD_HH:MM:SS", with the time part
40	    // optional -- into seconds since the Unix epoch (UTC).  Returns false for
41	    // anything it cannot fully account for, so a malformed stamp is reported
42	    // rather than silently mis-dated.  (std::chrono::parse would be tidier but
43	    // isn't available across all of our toolchains yet, matching the ECCAD
44	    // reader's hand-rolled CF parser.)
45	    bool ParseMpasXtime(const std::string& stamp, double& seconds_out)
46	    {
47	      const char* cursor = stamp.data();
48	      const char* const end = stamp.data() + stamp.size();
49	
50	      const auto take = [&](int& out, char delim) -> bool
51	      {
52	        const auto [next, ec] = std::from_chars(cursor, end, out);
53	        if (ec != std::errc{})
54	        {
55	          return false;
56	        }
57	        cursor = next;
58	        if (delim != '\0')
59	        {
60	          if (cursor == end || *cursor != delim)
61	          {
62	            return false;
63	          }
64	          ++cursor;
65	        }
66	        return true;
67	      };
68	
69	      int year = 0, month = 0, day = 0, hour = 0, minute = 0, second = 0;
70	      if (!take(year, '-') || !take(month, '-') || !take(day, '\0'))
71	      {
72	        return false;
73	      }
74	
75	      // MPAS separates the date and time with '_'; tolerate ' ' / 'T' too.
76	      if (cursor != end && (*cursor == '_' || *cursor == ' ' || *cursor == 'T'))
77	      {
78	        ++cursor;
79	        if (!take(hour, ':') || !take(minute, '\0'))
80	        {
81	          return false;
82	        }
83	        if (cursor != end && *cursor == ':')
84	        {
85	          ++cursor;
86	          if (!take(second, '\0'))
87	          {
88	            return false;
89	          }
90	        }
91	      }
92	
93	      // Reject anything left over rather than silently ignoring a bad stamp.
94	      if (cursor != end)
95	      {
96	        return false;
97	      }
98	
99	      const std::chrono::sys_seconds tp = UtcTimePoint(year, month, day, hour, minute, second);
100	      seconds_out = static_cast<double>(tp.time_since_epoch().count());
101	      return true;
102	    }
