200	  void UptempoReader::DiscoverSpecies()
201	  {
202	    available_species_.clear();
203	
204	    int n_vars;
205	    MIEM_NC_CHECK(nc_inq_nvars(ncid_, &n_vars));
206	
207	    // A flux field is any floating-point variable laid out on the mesh:
208	    // (Time, nCells), or (nCells) for a single-snapshot file. The variable's
209	    // own name is the inventory species name -- the reader makes no
